const items = $input.all();
const results = [];
for (const item of items) {
  const text = (item.json.message?.text || '').trim();
  const chatId = item.json.message?.chat?.id;
  const username = item.json.message?.from?.username || 'user';

  // Parse: /translate <lang> <text>
  const match = text.match(/^\/translate\s+(\w{2})\s+(.+)$/is);

  if (match) {
    const langMap = {
      en: 'English', id: 'Indonesian', ja: 'Japanese', ko: 'Korean',
      zh: 'Chinese', es: 'Spanish', fr: 'French', de: 'German',
      ar: 'Arabic', hi: 'Hindi', pt: 'Portuguese', ru: 'Russian',
      th: 'Thai', vi: 'Vietnamese', ms: 'Malay', tl: 'Filipino'
    };
    const targetLang = match[1].toLowerCase();
    results.push({
      json: {
        command: 'translate',
        targetLang,
        targetLangName: langMap[targetLang] || targetLang.toUpperCase(),
        sourceText: match[2].trim(),
        chatId, username,
        timestamp: new Date().toISOString()
      }
    });
  } else if (text === '/languages') {
    results.push({ json: { command: 'languages', chatId } });
  } else {
    results.push({ json: { command: 'help', chatId } });
  }
}
return results;

const items = $input.all();
const data = items[0].json;
const translated = data.responseData?.translatedText || 'Translation failed';
const detectedLang = data.responseData?.detectedLanguage || 'auto';
const match = data.responseData?.match || 0;

return [{
  json: {
    translatedText: translated,
    detectedLang,
    confidence: (match * 100).toFixed(0),
    sourceText: data.sourceText || '',
    targetLang: data.targetLang || '',
    targetLangName: data.targetLangName || ''
  }
}];
